  "findings": [
    {
      "benefit": "CI",
      "years": [2016, 2024],
      "pattern": "drift",
      "direction": "decrease",
      "magnitude": "~-0.36 peak-to-trough (2016-2019), then +0.35 level shift in 2020; sustained +0.07 to +0.10 above baseline 2020-2024",
      "confidence": 0.9,
      "evidence": [
        "ae_ci_by_year.csv: A/E declines YoY 2016-2019 (1.098→0.731), jumps to 1.067 in 2020, and remains elevated (1.055-1.100) through 2024.",
        "Deviations exceed 3-4x Poisson noise (σ≈0.03-0.04 given expected claims 600-1900), ruling out random fluctuation."
      ],
      "recommended_action": "Investigate claim reporting lags, underwriting/guideline changes, or diagnosis classification updates effective around 2019/2020; review CI expected claim basis; segment by age/gender (ae_ci_age_gender.csv) to isolate affected cohorts; update pricing/valuation assumptions for the sustained post-2020 elevation."
    }
  ]
}

